        public void AddLCPrintCount(int aiSchoolId, string asRegNo, int aiUserId, string sPrintDate)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("RegNo", asRegNo, SqlDbType.NVarChar);
                oSQLServerDbUtility.AddParameter("UserId", aiUserId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("PrintDate", sPrintDate, SqlDbType.NVarChar);
                oSQLServerDbUtility.ExecuteStoredProcedureOnServer("usp_AddLCPrintCount");
            }
        }
		
